        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Add Contact Tag</p>
          <p class="text-slate-600 text-sm">Add the inquiry-new tag action with consistent spelling.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Add Internal Notification</p>
          <p class="text-slate-600 text-sm">Configure who receives the notification and what it says.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">4</div>
        <div>
          <p class="font-semibold text-slate-900">Review Full Path</p>
          <p class="text-slate-600 text-sm">Check: correct form, accurate email, correct tag spelling, right recipient, all saved.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Add the Three Actions',
      lesson_number = 5,
      sort_order = 5,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Add the Three Actions';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Add the Three Actions

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 10 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 10 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'add-three-actions' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson add-three-actions not found in module 10';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the three actions in this workflow?', 
    '["Delete contact, send spam, ignore inquiry","Send confirmation email, add tag inquiry-new, send internal notification","Create invoice, charge payment, ship product","Block contact, unsubscribe, delete data"]'::jsonb,
    'Send confirmation email, add tag inquiry-new, send internal notification',
    'The three actions are: 1) Send a confirmation email to the contact, 2) Add the tag inquiry-new to organize the lead, 3) Send an internal notification to the team.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why use consistent tag spelling?', 
    '["It looks prettier","Small differences create separate tags and make lists harder to manage","It is required by law","Tags cannot be edited"]'::jsonb,
    'Small differences create separate tags and make lists harder to manage',
    'Consistent tag spelling is crucial. inquiry-new and Inquiry-New would be treated as two different tags, fragmenting your contact organization.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should the internal notification include?', 
    '["Only the contact''s favorite color","Name, email, phone, and expected response time","A sales pitch","Nothing, blank is fine"]'::jsonb,
    'Name, email, phone, and expected response time',
    'The internal notification should include the contact''s name, email, phone, and the expected response time so the team member has all information needed for follow-up.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
